+const form = document.getElementById('contactForm');
+const fullNameInput = document.getElementById('fullName');
+const emailInput = document.getElementById('email');
+const phoneInput = document.getElementById('phone');
+
+const fullNameError = document.getElementById('fullNameError');
+const emailError = document.getElementById('emailError');
+const phoneError = document.getElementById('phoneError');
+
+const touchedFields = new Set();
+
+// Validation rules
+const validators = {
+    fullName: (value) => {
+        if (!value.trim()) {
+            return 'Full name is required';
+        }
+        if (value.trim().length < 2) {
+            return 'Full name must be at least 2 characters';
+        }
+        return '';
+    },
+    email: (value) => {
+        if (!value.trim()) {
+            return 'Email address is required';
+        }
+        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
+        if (!emailRegex.test(value)) {
+            return 'Please enter a valid email address';
+        }
+        return '';
+    },
+    phone: (value) => {
+        if (!value.trim()) {
+            return '';
+        }
+        const phoneRegex = /^(\(\d{3}\)\s?\d{3}-\d{4}|\+1-\d{3}-\d{3}-\d{4})$/;
+        if (!phoneRegex.test(value)) {
+            return 'Please enter a valid phone number';
+        }
+        return '';
+    }
+};
+
+// Mark field as touched and validate
+function handleBlur(field, errorElement, validatorName) {
+    touchedFields.add(field.id);
+    validateField(field, errorElement, validatorName);
+}
+
+// Validate a single field
+function validateField(field, errorElement, validatorName) {
+    const error = validators[validatorName](field.value);
+    
+    if (error) {
+        field.classList.add('error');
+        errorElement.textContent = error;
+    } else {
+        field.classList.remove('error');
+        errorElement.textContent = '';
+    }
+}
+
+// Validate all fields
+function validateForm() {
+    let isValid = true;
+
+    const error1 = validators.fullName(fullNameInput.value);
+    if (error1) {
+        fullNameInput.classList.add('error');
+        fullNameError.textContent = error1;
+        isValid = false;
+    } else {
+        fullNameInput.classList.remove('error');
+        fullNameError.textContent = '';
+    }
+
+    const error2 = validators.email(emailInput.value);
+    if (error2) {
+        emailInput.classList.add('error');
+        emailError.textContent = error2;
+        isValid = false;
+    } else {
+        emailInput.classList.remove('error');
+        emailError.textContent = '';
+    }
+
+    const error3 = validators.phone(phoneInput.value);
+    if (error3) {
+        phoneInput.classList.add('error');
+        phoneError.textContent = error3;
+        isValid = false;
+    } else {
+        phoneInput.classList.remove('error');
+        phoneError.textContent = '';
+    }
+
+    return isValid;
+}
+
+// Event listeners for blur (only show errors for touched fields)
+fullNameInput.addEventListener('blur', () => handleBlur(fullNameInput, fullNameError, 'fullName'));
+emailInput.addEventListener('blur', () => handleBlur(emailInput, emailError, 'email'));
+phoneInput.addEventListener('blur', () => handleBlur(phoneInput, phoneError, 'phone'));
+
+// Form submission
+form.addEventListener('submit', (e) => {
+    e.preventDefault();
+    
+    if (validateForm()) {
+        console.log('Form submitted:', {
+            fullName: fullNameInput.value,
+            email: emailInput.value,
+            phone: phoneInput.value
+        });
+        form.reset();
+        touchedFields.clear();
+        fullNameInput.classList.remove('error');
+        emailInput.classList.remove('error');
+        phoneInput.classList.remove('error');
+    }
+});
+
